-- Pawny — Supabase schema and seed data
-- Paleisk šitą visą failą Supabase projekto SQL Editor'iuje (Dashboard → SQL Editor → New query).

create table if not exists public.animals (
  id bigint generated always as identity primary key,
  name text not null,
  type text not null,
  icon_key text not null default 'other',
  cat text not null check (cat in ('atvaziuoja','vietoje','globa')),
  tags jsonb not null default '[]'::jsonb,
  price text not null default 'Susitarti',
  area text,
  description text,
  rating text,
  photo text,
  sort_order bigint not null default extract(epoch from now()) * 1000,
  created_at timestamptz not null default now()
);

-- Įjungiam Row Level Security
alter table public.animals enable row level security;

-- Visi gali matyti skelbimus (viešas katalogas)
create policy "Public read access"
  on public.animals for select
  using (true);

-- Visi gali sukurti naują skelbimą per "Kelti gyvūną" formą
-- (paprastumo dėlei be autentifikacijos — vėliau gali apriboti su auth.uid())
create policy "Public insert access"
  on public.animals for insert
  with check (true);

-- Pradiniai 8 gyvūnai (tie patys, kurie buvo Claude prototipe)
insert into public.animals (name, type, icon_key, cat, tags, price, area, description, rating, photo, sort_order) values
  ('Herkulis', 'Ponis', 'pony', 'atvaziuoja', '["Šventė", "Gimtadienis", "Filmavimas"]'::jsonb, 'nuo 45 €/val', NULL, 'Herkulis — ramaus būdo ponis, pripratęs prie vaikų, triukšmo ir kamerų. Puikiai tinka gimtadieniams, šventėms kieme ir filmavimo aikštelėms, kur reikia gyvūno, kuris išliktų ramus dėmesio centre.', '4.9', 'data:image/jpeg;base64,', 1),
  ('Sviestukas ir Snaigė', 'Ožiukai', 'goat', 'atvaziuoja', '["Edukacija", "Šventė"]'::jsonb, 'nuo 30 €/val', NULL, 'Sviestukas ir Snaigė — žaismingas ožiukų duetas, mielai besileidžiantis glostomas ir fotografuojamas. Dažniausiai kviečiami į edukacines pamokas apie ūkio gyvūnus ir vaikų šventes lauke.', '4.8', 'data:image/jpeg;base64,', 2),
  ('Drakas', 'Barzdotoji agama', 'lizard', 'atvaziuoja', '["Edukacija mokykloms"]'::jsonb, 'nuo 35 €/pamoka', NULL, 'Drakas — rami barzdotoji agama, padedanti vaikams iš arti pažinti roplius saugioje aplinkoje. Puikiai tinka gamtos ir biologijos pamokoms mokykloje, kai norisi kažko netikėto.', '5.0', 'data:image/jpeg;base64,', 3),
  ('Tarakonų kolonija', 'Vabzdžiai', 'insect', 'atvaziuoja', '["Edukacija mokykloms"]'::jsonb, 'nuo 25 €/pamoka', NULL, 'Madagaskaro tarakonų kolonija — netikėtas, bet įtraukiantis eksponatas biologijos pamokoms apie vabzdžius, jų elgesį ir vaidmenį gamtoje. Vaikai gali stebėti ir, norėdami, paliesti.', '4.7', NULL, 4),
  ('Pitonas Kaa', 'Gyvatė', 'snake', 'vietoje', '["Edukacija", "Paglostymui"]'::jsonb, 'nuo 20 €/apsilankymas', NULL, 'Pitonas Kaa priimamas tik savo įprastoje, jam pažįstamoje aplinkoje — saugumo ir gyvūno gerovės sumetimais. Tinka edukacinėms ekskursijoms ir tiems, kas nori iš arti pamatyti bei paglostyti gyvatę.', '4.9', NULL, 5),
  ('Alpaka Snaigė', 'Alpaka', 'alpaca', 'atvaziuoja', '["Filmavimas", "Šventė"]'::jsonb, 'nuo 60 €/val', NULL, 'Alpaka Snaigė — fotogeniškas, ramus gyvūnas, dažnai kviečiamas į filmavimo aikšteles reklamoms ir foto sesijoms, taip pat į šventes lauke, kur reikia įsimintino akcento.', '5.0', NULL, 6),
  ('Bimas', 'Šuo', 'dog', 'globa', '["Draugija", "Savaitei"]'::jsonb, 'Auka gerai valiai', NULL, 'Bimas — prieglaudos šuo, ieškantis laikinų globėjų savaitei. Puiki galimybė pabandyti gyvūno draugiją ir padėti jam socializuotis prieš randant nuolatinius namus.', '5.0', NULL, 7),
  ('Kiaulytė Pelėda', 'Mini kiaulė', 'pig', 'atvaziuoja', '["Šventė", "Edukacija"]'::jsonb, 'nuo 40 €/val', NULL, 'Mini kiaulytė Pelėda — mėgstama vaikų šventėse ir edukacinėse programose apie ūkio gyvūnus. Smalsi, draugiška ir puikiai jaučiasi tarp žmonių.', '4.8', NULL, 8);
